Suppose Assumptions \textnormal{(A1)}–\textnormal{(A5)} hold. Then for all \(T \ge 1\),
\begin{flalign*}
\mathbb{P}\Bigg(
\text{Regret}(NT)
&\;\le\;
N\,T_{0}\,e_{\max}
\;+\;
\frac{4\,e_{\max}\,k_{\mu}}{c_{\mu}\,\hat\sigma_{\min}}\;
\beta_{\widetilde T}\,
\sqrt{N\,T}\times
\Big[
\sqrt{\mathcal{V}_{\widetilde{T}}}
+
\beta_{\widetilde T}\,
\sqrt{\widetilde T\,\mathcal{V}_{\widetilde{T}}}
\Big]
\Bigg)
\;\ge\;
1 - \delta.
\end{flalign*}

Suppose Assumptions \textnormal{(A1)}–\textnormal{(A5)} hold. Then for all \(T \ge 1\),
\begin{align*}
\mathbb{P}\Bigg(
&\operatorname{Regret}(NT)
\;\le\;\,
T_0 N e_{\max} 
+ 
\frac{4\,e_{\max}\,k_{\mu}}{c_{\mu}\,\hat\sigma_{\min}}\,
\beta_{\widetilde T}\,
\sqrt{\sum_{t=1}^{T} M_t \cdot \mathcal{V}_{\widetilde{T}}}  \\
&+ 2\,\beta_{\widetilde T}\,
\sqrt{H \sum_{t=1}^{T} M_t \cdot \mathcal{V}_{\widetilde{T}}} + 
\frac{4e_{\max} \,c_z}
     {c_\mu \hat\sigma_{\min} \sqrt{\tfrac12 w_{\min}p_{\min}}}
\cdot \sqrt{T} \cdot  \beta_{\widetilde T}
\Bigg)\\
&\;\ge\;
1 - \delta.
\end{align*}
